import{_ as r,c as e,o,a4 as t}from"./chunks/framework.BU14wsQo.js";const c=JSON.parse('{"title":"AI资讯日报 2026/5/13","description":"Claude 获得记忆能力，阶跃星辰与 Perceptron 推进开源模型，Google、Anthropic、OpenAI 和 xAI 继续把 AI 接进浏览器、法律、桌面与移动系统；美国 GenAI 采购新规、AI 教育并购、攻击链复现、论文数据泄露和软件供应链风险共同抬高治理门槛。","frontmatter":{"linkTitle":"05-13 AI日报","title":"AI资讯日报 2026/5/13","weight":19,"breadcrumbs":false,"comments":true,"description":"Claude 获得记忆能力，阶跃星辰与 Perceptron 推进开源模型，Google、Anthropic、OpenAI 和 xAI 继续把 AI 接进浏览器、法律、桌面与移动系统；美国 GenAI 采购新规、AI 教育并购、攻击链复现、论文数据泄露和软件供应链风险共同抬高治理门槛。"},"headers":[],"relativePath":"AI/daily/cn/2026-05/2026-05-13.md","filePath":"AI/daily/cn/2026-05/2026-05-13.md","lastUpdated":1778638076000}'),n={name:"AI/daily/cn/2026-05/2026-05-13.md"};function s(i,a,l,h,g,d){return o(),e("div",null,[...a[0]||(a[0]=[t(`<h1 align="center">2026-05-13 AI资讯日报</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claude 记忆能力上线，Google 在 Chrome 搜索框测试 Gemini，AI 正在从聊天框钻进浏览器、邮箱、桌面和手机系统 🚀</span></span>
<span class="line"><span>阶跃星辰 Step 2 Mini、Perceptron AI R0 与 MatterSim v2.0 继续刷新小模型、开源模型和科学模拟的可用边界 🧠</span></span>
<span class="line"><span>OpenAI Codex 获得 Computer Use，Android 锁屏助手、Cursor Teams、Statewright 和 ADK 把智能体能力继续产品化 🛠️</span></span>
<span class="line"><span>美国 GenAI 采购新规、印度法院采信 AI 报告、Aflac 入侵与 arXiv 元数据泄露提醒大家：部署越深，治理越硬 ☁️</span></span>
<span class="line"><span>Riley AI、IXL Learning、Cohere 3000 多万美元 ARR 与 Naveen Rao 新公司融资，让教育、企业搜索和 AI 编程商业化继续升温 ✨</span></span>
<span class="line"><span>社区侧关注 token 经济学、失败叙事、HTML 输出、数据导出和 Parameters Golf，AI 讨论正在从“模型多强”转向“系统怎么用” (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-claude-获得跨会话记忆能力" tabindex="-1">1. Claude 获得跨会话记忆能力 <a class="header-anchor" href="#_1-claude-获得跨会话记忆能力" aria-label="Permalink to &quot;1. Claude 获得跨会话记忆能力&quot;">​</a></h3><p><strong>Anthropic</strong> 为 <strong>Claude</strong> 推出记忆功能，用户可以让模型在项目、偏好、工作习惯和长期上下文之间保持连续性 🚀。这让助手从“每次重新认识你”进一步变成可持续协作的 <strong>个人工作伙伴</strong>；真正的关键不只是记住事实，而是让模型在后续任务里减少反复解释与上下文重建成本。</p><h3 id="_2-阶跃星辰开源-step-2-mini" tabindex="-1">2. 阶跃星辰开源 Step 2 Mini <a class="header-anchor" href="#_2-阶跃星辰开源-step-2-mini" aria-label="Permalink to &quot;2. 阶跃星辰开源 Step 2 Mini&quot;">​</a></h3><p><strong>阶跃星辰</strong> 发布并开源 <strong>Step 2 Mini</strong>，这个 <strong>30B</strong> 级别 MoE 模型采用两阶段预训练，使用 <strong>15T</strong> token，并通过 <strong>GQA</strong>、<strong>3D-RoPE</strong> 与 <strong>MoE</strong> 架构支撑 <strong>32k</strong> 上下文。它强调 <strong>35 亿激活参数</strong> 下的高性价比推理，对追求低成本部署的中文与多语种场景很有吸引力 🧠。</p><h3 id="_3-thinking-machines-预告首个产品" tabindex="-1">3. Thinking Machines 预告首个产品 <a class="header-anchor" href="#_3-thinking-machines-预告首个产品" aria-label="Permalink to &quot;3. Thinking Machines 预告首个产品&quot;">​</a></h3><p><strong>Thinking Machines</strong> 预告将在数月内推出第一款产品，创始人 <strong>Mira Murati</strong> 表示方向会聚焦 <strong>AI 研究</strong> 与 <strong>编码</strong>，并且“研究人员会很喜欢”。这个信号意味着前沿实验室正在把研究工作流、代码协作与模型能力打包成更直接的生产工具 ✨。</p><h3 id="_4-perceptron-ai-发布-r0-系列开源推理模型" tabindex="-1">4. Perceptron AI 发布 R0 系列开源推理模型 <a class="header-anchor" href="#_4-perceptron-ai-发布-r0-系列开源推理模型" aria-label="Permalink to &quot;4. Perceptron AI 发布 R0 系列开源推理模型&quot;">​</a></h3><p><strong>Perceptron AI</strong> 推出首批 <strong>R0</strong> 系列开源模型，强调在 <strong>最小推理 token</strong> 消耗下达到接近闭源模型的效果。该系列包含 <strong>3B</strong> 与 <strong>32B</strong> 两个版本，并在 <strong>KRIS-Bench</strong>、函数调用、数学和问答任务上展示较强表现，适合对推理成本敏感的工程场景 ( •̀ ω •́ )。</p><h3 id="_5-微软-mattersim-v2-0-服务材料科学模拟" tabindex="-1">5. 微软 MatterSim v2.0 服务材料科学模拟 <a class="header-anchor" href="#_5-微软-mattersim-v2-0-服务材料科学模拟" aria-label="Permalink to &quot;5. 微软 MatterSim v2.0 服务材料科学模拟&quot;">​</a></h3><p><strong>微软研究院 AI for Science</strong> 开源 <strong>MatterSim v2.0</strong>，定位为通用 <strong>AI 原子间势能模型</strong>。它能在多种温度和压力下支持材料性质预测，比传统方法快 <strong>5-6 倍</strong>，把 AI 从文本与代码场景继续推向科学计算基础设施 🧪。</p><h3 id="_6-google-在-chrome-地址栏测试-gemini" tabindex="-1">6. Google 在 Chrome 地址栏测试 Gemini <a class="header-anchor" href="#_6-google-在-chrome-地址栏测试-gemini" aria-label="Permalink to &quot;6. Google 在 Chrome 地址栏测试 Gemini&quot;">​</a></h3><p><strong>Google</strong> 正在测试把 <strong>Gemini</strong> 直接嵌入 <strong>Chrome</strong> 搜索框的能力，用户可在地址栏中完成复杂问题理解与任务辅助。这不是一个小入口改动：浏览器搜索框本来就是互联网使用的起点，AI 一旦进入这里，就会天然参与信息检索、网页理解和多步骤操作 🚀。</p><h3 id="_7-claude-进入法律研究工作流" tabindex="-1">7. Claude 进入法律研究工作流 <a class="header-anchor" href="#_7-claude-进入法律研究工作流" aria-label="Permalink to &quot;7. Claude 进入法律研究工作流&quot;">​</a></h3><p><strong>Anthropic</strong> 发布面向法律行业的 <strong>Claude for legal work</strong>，主打法律研究、文档摘要、复杂资料检索和合同审阅等高密度文本任务。法律场景对准确性、出处和可审计性要求很高，模型公司选择从这里切入，说明企业级垂直工作流正在成为重要战场 ☁️。</p><h3 id="_8-google-symphony-重新理解表格问答" tabindex="-1">8. Google Symphony 重新理解表格问答 <a class="header-anchor" href="#_8-google-symphony-重新理解表格问答" aria-label="Permalink to &quot;8. Google Symphony 重新理解表格问答&quot;">​</a></h3><p><strong>Google Cloud</strong> 介绍 <strong>Symphony</strong>，用于在真实世界表格上完成问题回答和数据理解。相比只让模型读一张表，真正难点在于识别字段含义、跨列推理、处理脏数据和保持结果可解释；这类能力会直接影响企业内部分析助手的可用性 🧠。</p><h3 id="_9-grok-接入-gmail-与-google-drive" tabindex="-1">9. Grok 接入 Gmail 与 Google Drive <a class="header-anchor" href="#_9-grok-接入-gmail-与-google-drive" aria-label="Permalink to &quot;9. Grok 接入 Gmail 与 Google Drive&quot;">​</a></h3><p><strong>xAI</strong> 为 <strong>Grok</strong> 推出连接器，允许其接入 <strong>Gmail</strong> 与 <strong>Google Drive</strong>，用于搜索邮件、文档与个人资料库。个人数据连接器正在成为 AI 助手竞争的基础设施，但它同时也把权限、隐私和误操作风险摆到台前，体验与治理必须一起做 (｀・ω・´)。</p><h3 id="_10-cursor-teams-面向小型团队上线" tabindex="-1">10. Cursor Teams 面向小型团队上线 <a class="header-anchor" href="#_10-cursor-teams-面向小型团队上线" aria-label="Permalink to &quot;10. Cursor Teams 面向小型团队上线&quot;">​</a></h3><p><strong>Cursor</strong> 推出面向小团队的 <strong>Teams</strong> 方案，提供共享规则、项目索引、集中计费和多人协作能力。AI 编程工具的用户正从个人开发者扩展到团队管理者，接下来比拼的不只是补全质量，还有权限、规范、上下文同步和代码库级协作体验 🛠️。</p><h3 id="_11-openai-codex-获得-computer-use" tabindex="-1">11. OpenAI Codex 获得 Computer Use <a class="header-anchor" href="#_11-openai-codex-获得-computer-use" aria-label="Permalink to &quot;11. OpenAI Codex 获得 Computer Use&quot;">​</a></h3><p><strong>OpenAI Codex</strong> 增加 <strong>Computer Use</strong> 能力，智能体可以操作浏览器和网页界面完成此前只能人工点击的任务。对开发者来说，这会让端到端验证、后台配置、可视化检查和跨系统操作更接近自动化闭环；代码智能体正在从“写文件”走向“使用软件” 🚀。</p><h3 id="_12-android-锁屏助手探索移动入口" tabindex="-1">12. Android 锁屏助手探索移动入口 <a class="header-anchor" href="#_12-android-锁屏助手探索移动入口" aria-label="Permalink to &quot;12. Android 锁屏助手探索移动入口&quot;">​</a></h3><p>有项目展示面向 <strong>Android</strong> 的锁屏 AI 助手，用户无需解锁即可通过自然语言触发查询、提醒或简单任务。移动端 AI 入口会越来越靠近系统层：谁能在低摩擦、低风险的场景里稳定完成任务，谁就更可能成为日常助手的默认入口 ✨。</p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-gear-让长视频定位更精细" tabindex="-1">1. GeAR 让长视频定位更精细 <a class="header-anchor" href="#_1-gear-让长视频定位更精细" aria-label="Permalink to &quot;1. GeAR 让长视频定位更精细&quot;">​</a></h3><p>论文 <strong>GeAR</strong> 关注细粒度 <strong>Video Moment Retrieval</strong>，试图在长视频中更准确地定位用户描述的片段。随着视频成为知识、娱乐和工作记录的主格式，模型能否把“找到某一刻”做准，会直接影响视频检索、剪辑、审查和智能代理处理多媒体资料的效率 🎬。</p><h3 id="_2-parameters-golf-激发极限模型压缩实验" tabindex="-1">2. Parameters Golf 激发极限模型压缩实验 <a class="header-anchor" href="#_2-parameters-golf-激发极限模型压缩实验" aria-label="Permalink to &quot;2. Parameters Golf 激发极限模型压缩实验&quot;">​</a></h3><p>社区发起 <strong>Parameters Golf</strong> 挑战，目标是在最少参数下训练模型完成从 <strong>0</strong> 数到 <strong>999</strong> 的任务。这类实验看似像技术游戏，本质上是在追问模型容量、记忆、泛化和训练目标之间的边界；当推理成本成为瓶颈，小模型能力极限会越来越重要 🧩。</p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-美国发布-genai-采购实施新规" tabindex="-1">1. 美国发布 GenAI 采购实施新规 <a class="header-anchor" href="#_1-美国发布-genai-采购实施新规" aria-label="Permalink to &quot;1. 美国发布 GenAI 采购实施新规&quot;">​</a></h3><p>美国政府发布 <strong>GenAI 采购实施新规</strong>，为联邦机构采购生成式 AI 工具设定更清晰的合规、风险与评估要求。政策开始从原则声明走向采购细则，意味着 AI 产品若想进入公共部门，需要更强的透明度、安全说明、性能证据与供应商责任机制 ☁️。</p><h3 id="_2-ai-教育平台-riley-完成-21-亿美元并购" tabindex="-1">2. AI 教育平台 Riley 完成 21 亿美元并购 <a class="header-anchor" href="#_2-ai-教育平台-riley-完成-21-亿美元并购" aria-label="Permalink to &quot;2. AI 教育平台 Riley 完成 21 亿美元并购&quot;">​</a></h3><p>AI 教育平台 <strong>Riley AI</strong> 被以 <strong>21 亿美元</strong> 收购，显示教育科技正在重新估值 AI 个性化学习、练习反馈和教学运营自动化。教育场景的核心不是炫技，而是持续提升学习效果、降低老师重复劳动，并把数据闭环做得足够稳 (๑•̀ㅂ•́)و✧。</p><h3 id="_3-印度法院采信-chatgpt-报告" tabindex="-1">3. 印度法院采信 ChatGPT 报告 <a class="header-anchor" href="#_3-印度法院采信-chatgpt-报告" aria-label="Permalink to &quot;3. 印度法院采信 ChatGPT 报告&quot;">​</a></h3><p>印度一地方法院在裁决中采信 <strong>ChatGPT</strong> 生成的报告，引发法律界关于 AI 输出可采性、证据标准和责任主体的讨论。模型可以辅助检索与整理，但如果进入裁判依据，就必须面对来源验证、可复现性和错误归责问题 🛡️。</p><h3 id="_4-linus-torvalds-讨论-linux-内核中的-ai" tabindex="-1">4. Linus Torvalds 讨论 Linux 内核中的 AI <a class="header-anchor" href="#_4-linus-torvalds-讨论-linux-内核中的-ai" aria-label="Permalink to &quot;4. Linus Torvalds 讨论 Linux 内核中的 AI&quot;">​</a></h3><p><strong>Linus Torvalds</strong> 在日本开源峰会谈到 <strong>Linux 内核中的 AI</strong>，也回应了维护者群体老龄化问题。基础软件社区对 AI 的态度通常更务实：欢迎能降低维护负担的工具，但不会接受难以审查、难以解释、难以负责的黑盒改动 🛠️。</p><h3 id="_5-aflac-遭遇入侵并疑似泄露敏感数据" tabindex="-1">5. Aflac 遭遇入侵并疑似泄露敏感数据 <a class="header-anchor" href="#_5-aflac-遭遇入侵并疑似泄露敏感数据" aria-label="Permalink to &quot;5. Aflac 遭遇入侵并疑似泄露敏感数据&quot;">​</a></h3><p>保险公司 <strong>Aflac</strong> 遭攻击，可能泄露社会安全号、健康信息和理赔记录等敏感数据。AI 时代的数据泄露风险会被进一步放大，因为被盗数据不仅能用于传统诈骗，还能驱动更精准的钓鱼、身份冒充和自动化攻击链 (；′⌒\`)。</p><h3 id="_6-arxiv-元数据泄露暴露论文评审身份" tabindex="-1">6. arXiv 元数据泄露暴露论文评审身份 <a class="header-anchor" href="#_6-arxiv-元数据泄露暴露论文评审身份" aria-label="Permalink to &quot;6. arXiv 元数据泄露暴露论文评审身份&quot;">​</a></h3><p>研究人员发现 <strong>arXiv</strong> 的 <strong>HTML 源码元数据</strong> 泄露了部分会议论文评审身份，影响 <strong>20 多个会议</strong>、<strong>12 个工作坊</strong> 与约 <strong>10 万</strong> 名评审。学术基础设施的细节漏洞也会破坏匿名评审制度，AI 论文投稿量继续上升后，这类系统性风险会更难忽视。</p><h3 id="_7-中科院网安所复现-ai-自动化攻击链" tabindex="-1">7. 中科院网安所复现 AI 自动化攻击链 <a class="header-anchor" href="#_7-中科院网安所复现-ai-自动化攻击链" aria-label="Permalink to &quot;7. 中科院网安所复现 AI 自动化攻击链&quot;">​</a></h3><p>中科院网安所展示 <strong>AI 驱动的自动化网络攻击链</strong>：通过自然语言命令，AI Agent 可完成信息收集、漏洞扫描与利用动作。这不是“AI 会不会攻击”的抽象讨论，而是把安全团队必须面对的自动化攻防能力摆到了现实台面 🛡️。</p><h3 id="_8-cohere-和-naveen-rao-新公司获得资本关注" tabindex="-1">8. Cohere 和 Naveen Rao 新公司获得资本关注 <a class="header-anchor" href="#_8-cohere-和-naveen-rao-新公司获得资本关注" aria-label="Permalink to &quot;8. Cohere 和 Naveen Rao 新公司获得资本关注&quot;">​</a></h3><p><strong>Cohere</strong> 披露企业搜索业务年化收入超过 <strong>3000 万美元</strong>，显示企业知识检索仍是大模型落地的核心场景；同时前 <strong>Databricks</strong> 高管 <strong>Naveen Rao</strong> 正为新 AI 编程公司以 <strong>20 亿美元</strong> 估值融资。企业搜索和 AI 编程，一个管知识入口，一个管生产力入口，都是资金持续追逐的高频刚需 🚀。</p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-statewright-用-ai-生成-playwright-测试" tabindex="-1">1. Statewright 用 AI 生成 Playwright 测试 <a class="header-anchor" href="#_1-statewright-用-ai-生成-playwright-测试" aria-label="Permalink to &quot;1. Statewright 用 AI 生成 Playwright 测试&quot;">​</a></h3><p><strong>Statewright</strong> 是一个新的开发者工具，能借助 AI 直接生成 <strong>Playwright</strong> 自动化测试。它解决的是软件开发里很现实的缺口：AI 可以快速写功能，但如果测试覆盖跟不上，团队会把速度红利重新花在排查回归上 ( •̀ ω •́ )。</p><h3 id="_2-google-adk-加速多智能体原型" tabindex="-1">2. Google ADK 加速多智能体原型 <a class="header-anchor" href="#_2-google-adk-加速多智能体原型" aria-label="Permalink to &quot;2. Google ADK 加速多智能体原型&quot;">​</a></h3><p><strong>Google ADK</strong> 教程演示了如何快速构建多智能体系统，包括角色划分、工具调用和协作流程。多智能体真正落地时，难点通常不是“多开几个模型”，而是任务边界、共享状态、失败恢复和可观测性；框架化工具会降低试错成本 🛠️。</p><h3 id="_3-claude-code-接入-codex-插件生态" tabindex="-1">3. Claude Code 接入 Codex 插件生态 <a class="header-anchor" href="#_3-claude-code-接入-codex-插件生态" aria-label="Permalink to &quot;3. Claude Code 接入 Codex 插件生态&quot;">​</a></h3><p>社区展示 <strong>Claude Code</strong> 与 <strong>Codex</strong> 插件联动的工作流，让工程智能体能够利用更丰富的插件能力完成本地开发任务。插件化正在成为 AI 编程工具的第二增长曲线：模型负责推理，插件负责触达具体系统，二者结合才像真正的开发环境 🚀。</p><h3 id="_4-开放模型生态继续扩张" tabindex="-1">4. 开放模型生态继续扩张 <a class="header-anchor" href="#_4-开放模型生态继续扩张" aria-label="Permalink to &quot;4. 开放模型生态继续扩张&quot;">​</a></h3><p>关于 <strong>开放模型生态</strong> 的讨论继续升温：小模型、MoE、开源推理和本地部署工具正在把开发者从单一闭源接口中解放出来。对企业来说，开源不只是省钱，还意味着可控部署、可审计行为和更灵活的模型路由策略 ☁️。</p><h3 id="_5-parquet-包名劫持暴露软件供应链风险" tabindex="-1">5. Parquet 包名劫持暴露软件供应链风险 <a class="header-anchor" href="#_5-parquet-包名劫持暴露软件供应链风险" aria-label="Permalink to &quot;5. Parquet 包名劫持暴露软件供应链风险&quot;">​</a></h3><p>社区披露与 <strong>Parquet</strong> 相关的 npm 包名劫持案例，<strong>19 岁</strong> 开发者被指控制 <strong>160</strong> 个包名、发布 <strong>373 versions</strong>，总下载量约 <strong>8520 亿</strong>。当 AI 代码工具自动安装依赖、自动生成配置时，软件供应链污染会变得更隐蔽，也更值得自动化扫描 🧯。</p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-token-使用量可能成为新-kpi" tabindex="-1">1. token 使用量可能成为新 KPI <a class="header-anchor" href="#_1-token-使用量可能成为新-kpi" aria-label="Permalink to &quot;1. token 使用量可能成为新 KPI&quot;">​</a></h3><p>社区围绕 “<strong>tokens are the new KPI</strong>” 展开讨论，认为 token 消耗会像云资源、搜索流量或广告点击一样，成为衡量 AI 产品使用深度的重要指标。但这个指标也有陷阱：token 多不等于价值高，真正该看的是任务完成率、成本效率和用户留存 (｀・ω・´)。</p><h3 id="_2-ai-叙事进入失败与选择期" tabindex="-1">2. AI 叙事进入失败与选择期 <a class="header-anchor" href="#_2-ai-叙事进入失败与选择期" aria-label="Permalink to &quot;2. AI 叙事进入失败与选择期&quot;">​</a></h3><p>有观点总结当下 <strong>AI 失败叙事</strong>：部分产品被过度包装，部分团队低估了数据、工作流和分发难度。热潮不会线性上升，下一阶段更像筛选期，能穿越周期的通常是把真实问题、成本结构和交付体验讲清楚的团队 🧭。</p><h3 id="_3-karpathy-继续强调-html-输出" tabindex="-1">3. Karpathy 继续强调 HTML 输出 <a class="header-anchor" href="#_3-karpathy-继续强调-html-输出" aria-label="Permalink to &quot;3. Karpathy 继续强调 HTML 输出&quot;">​</a></h3><p><strong>Andrej Karpathy</strong> 再次强调，AI 输出会从纯 Markdown 走向更丰富的 <strong>HTML</strong> 与交互界面。这个判断和工具趋势高度一致：当模型能生成可点击、可运行、可检查的界面时，回答就不再只是文本，而会变成任务执行的一部分 ✨。</p><h3 id="_4-chatgpt-数据导出引发个人知识库讨论" tabindex="-1">4. ChatGPT 数据导出引发个人知识库讨论 <a class="header-anchor" href="#_4-chatgpt-数据导出引发个人知识库讨论" aria-label="Permalink to &quot;4. ChatGPT 数据导出引发个人知识库讨论&quot;">​</a></h3><p>用户开始更关注 <strong>ChatGPT 数据导出</strong> 与个人知识管理，希望把长期对话、项目上下文和偏好沉淀到可迁移的资料库里。记忆能力越强，用户对数据可控性、可导出性和跨工具迁移的要求也会越高 ( •̀ ω •́ )。</p><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>入口竞争正在系统化。</strong> Chrome 地址栏、Android 锁屏、Gmail、Google Drive 和桌面操作能力说明 AI 助手正在抢占默认入口 🚀。</li><li><strong>小模型和开源模型不是配角。</strong> Step 2 Mini、Perceptron R0、MatterSim 和 Parameters Golf 都在证明成本、部署与可控性会持续塑造模型路线 🧠。</li><li><strong>企业落地开始拼垂直工作流。</strong> 法律、教育、企业搜索、表格问答和 AI 编程融资都指向更具体、更高频的生产场景 ☁️。</li><li><strong>智能体工具链需要测试和治理。</strong> Statewright、ADK、Codex Computer Use 与 Claude Code 插件让自动化更强，也让验证、权限和回滚更关键 🛠️。</li><li><strong>安全风险已经进入供应链和制度层。</strong> Aflac、arXiv、Parquet 包名劫持和 AI 攻击链说明，AI 时代的安全问题不只在模型本身 🛡️。</li><li><strong>社区讨论正在从能力崇拜转向系统设计。</strong> token KPI、失败叙事、HTML 输出与数据导出都在追问一个问题：AI 到底如何稳定创造价值 (๑•̀ㅂ•́)و✧。</li></ul>`,72)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
